PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE applications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        batch_id TEXT NOT NULL,
        applicant_code TEXT NOT NULL,
        city TEXT NOT NULL DEFAULT '深圳',
        main_applicant TEXT NOT NULL,
        id_card TEXT,
        house_type TEXT,
        queue TEXT,
        talent_type TEXT,
        family_size INTEGER,
        member_names TEXT,
        verify_status TEXT,
        ballot_seq INTEGER,
        selection_result TEXT,
        selected_unit TEXT,
        notices_json TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (batch_id, applicant_code),
        FOREIGN KEY (batch_id) REFERENCES batches(batch_id)
    );
CREATE TABLE batches (
        batch_id TEXT PRIMARY KEY,
        project_id INTEGER NOT NULL,
        city TEXT NOT NULL DEFAULT '深圳',
        district TEXT,
        batch_seq INTEGER,
        housing_type TEXT,
        total_units INTEGER,
        one_bedroom_units INTEGER,
        two_bedroom_units INTEGER,
        three_bedroom_units INTEGER,
        four_bedroom_units INTEGER,
        other_units INTEGER,
        average_price REAL,
        deposit_amount REAL,
        sales_mode TEXT,
        has_regular_sales_exit INTEGER,
        reception_location TEXT,
        consultation_phone TEXT,
        booking_channel TEXT,
        sub_start_date TEXT,
        sub_end_date TEXT,
        current_stage TEXT,
        notices_json TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (project_id) REFERENCES projects(id)
    );
