CREATE TABLE households (
        code TEXT PRIMARY KEY,
        batch TEXT,
        source_file TEXT,
        seq INTEGER,
        house_type TEXT,
        queue TEXT,
        main_applicant TEXT,
        main_id_card TEXT,
        talent_type TEXT,
        intention TEXT,
        family_size INTEGER,
        member_names TEXT
    );
CREATE TABLE members (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        code TEXT,
        name TEXT,
        id_card TEXT,
        role TEXT,
        is_main INTEGER,
        house_type TEXT,
        queue TEXT,
        talent_type TEXT,
        source_file TEXT,
        FOREIGN KEY(code) REFERENCES households(code)
    );
CREATE TABLE notices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        city TEXT NOT NULL DEFAULT '深圳',
        district TEXT,
        project_id INTEGER,
        batch_id TEXT,
        category TEXT,
        title TEXT NOT NULL,
        publish_date TEXT,
        url TEXT NOT NULL UNIQUE,
        summary TEXT,
        content_text TEXT,
        attachments_json TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (project_id) REFERENCES projects(id),
        FOREIGN KEY (batch_id) REFERENCES batches(batch_id)
    );
INSERT INTO "notices" VALUES(2,'深圳','市住建局',NULL,'住保售〔2026〕077号批次','综合公告','关于安居型商品房配售有关事项的通知（2026077-1）','2026-09-29','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_13003239.html','','',NULL,'2026-11-07 03:25:42');
INSERT INTO "notices" VALUES(3,'深圳','市住建局',155,'住保售〔2026〕077号批次','认购通告','深圳市住房保障署安居型商品房配售通告（住保售〔2026〕077号）','2026-09-29','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_13003236.html','《关于安居型商品房配售有关事项的通知》（2026077-1）已在深圳市住房和建设局官方网站发布。现就缙熙园项目安居型商品房（以下简称本批次住房）的配售对象、房源安排、选房方式、配售程序等有关事项通告如下： 一、申请条件 （一）认购本批次住房','《关于安居型商品房配售有关事项的通知》（2026077-1）已在深圳市住房和建设局官方网站发布。现就缙熙园项目安居型商品房（以下简称本批次住房）的配售对象、房源安排、选房方式、配售程序等有关事项通告如下：
一、申请条件
（一）认购本批次住房，按照申请家庭资格条件分为三个队列，具体如下：
第一队列：属于深圳市安居型商品房在册轮候家庭且仍符合安居型商品房轮候申请条件，或在本通告认购截止前符合安居型商品房申请条件且经深圳市人力资源和社会保障局认定的领军人才（人才证书在有效期内或人才证书虽不在有效期内但期末评估合格）。
第二队列：申请人、共同申请人均具有本市户籍，申请人配偶属现役军人的，可以不受户籍限制，申请人的未成年子女因就学而将户籍迁出本市的，视为具有本市户籍；申请人参加本市社会保险累计缴费5年以上，申请人为本科及以上学历的，参加本市社会保险累计缴费3年以上；申请人为单身的，应当年满35周岁。
第三队列：申请人具有本市户籍；申请人参加本市社会保险累计缴费5年以上，申请人为本科及以上学历的，参加本市社会保险累计缴费3年以上；申请人配偶、未成年子女不受本市户籍限制，未具有本市户籍的申请人配偶在本市正常缴纳社会保险，但在本市退休的除外；申请人为单身的，应当年满30周岁。
属于以下特殊群体的，不受缴纳社会保险时间限制：1.申请人、共同申请人属于经民政部门或退役军人管理部门认定的抚恤定补优抚对象；2.申请人、共同申请人属于经残疾人联合会或退役军人管理部门认定的残疾人。
（二）申请家庭在认购截止日前，还应符合下列条件：
1.申请人、共同申请人均未在本市拥有任何形式自有住房，且在申请受理日之前5年内未在本市转让过或者因离婚分割过自有住房。
2.申请人、共同申请人在本市未购买过准成本房、全成本房、社会微利房、全成本微利房、单位集资建房、经济适用住房、安居型商品房（含面向人才配售）、共有产权住房等政策性住房，未享受过人才购房补贴、高层次人才奖励补贴等购房优惠政策。
（三）申请人应当以家庭为单位提出本批次住房申请，申请人的配偶、未满18周岁（判定时点为本通告发布之日）的子女应当列为共同申请人，申请人年满18周岁的子女不能列为共同申请人。未满18周岁的子女列为共同申请人的，不影响其成年后单独组成家庭或者达到规定年龄后以单身居民身份申请深圳市住房保障。申请人父母、申请人配偶父母具有本市户籍的，可以作为共同申请人。投靠子女取得深圳市户籍的居民，只能作为共同申请人。
二、申请材料
深圳市安居型商品房在册轮候家庭无需另行提交材料。其他申请认购家庭应当通过线上提交以下材料：
（一）住房认购申请表；
（二）申请人的身份证、户口簿，共同申请人的身份证、户口簿（或出生证、收养证明、公证书等关系证明材料）及其他户籍证明；
（三）申请人配偶属现役军人的，提供军官证、士兵证；
（四）申请人及共同申请人的婚姻状况证明（初婚的提供结婚证；离异的提供离婚证和离婚协议、生效的法院判决书或调解书等离婚证明材料；再婚的提供结婚证及前段婚姻离婚证明材料；丧偶的提供丧偶证明材料；未婚的无须提供婚姻状况证明）。
（五）以下人才证明材料之一：
1.学历（学位）证书；
2.由深圳市人力资源和社会保障局出具的高层次人才证书。
（六）申请人或共同申请人属于残疾人的，提供在认购截止日前由残疾人联合会或退役军人管理部门颁发的有效残疾人证。
三、房源安排
本批次配售住房248套，其中：建筑面积约68平方米两房户型194套、建筑面积约89平方米三房户型54套。
（一）单身居民及二至三人家庭可根据自身意愿认购本批次住房的两房户型。
（二）领军人才、四人及以上家庭可根据自身意愿认购本批次住房的两房户型或三房户型。
四、配售方式
本批次住房实行集中认购、分队列摇号排序选房。
（一）认购申请方式
认购申请家庭可线上提交认购意向。
（二）选房方式
本批次住房按两房户型和三房户型分别组织选房。
第一队列第一序位为领军人才认购申请家庭，其选房排位排在本次认购的所有轮候家庭之前，领军人才之间的选房排位按照提交安居型商品房申请时间的先后顺序确定。第二序位为按深圳市安居型商品房轮候册排位确定的在册认购申请家庭，其中申请人或共同申请人如属民政部门或退役军人管理部门认定的抚恤定补优抚对象，或为拥有残疾人联合会或退役军人管理部门颁发的有效残疾人证的残疾人，有优先选房权利，选房排位依据深圳市安居型商品房轮候册的轮候排序确定。
第二、三队列选房顺序通过公证摇号确定。
选房顺序依次为第一队列、第二队列、第三队列，每个队列的认购申请家庭按确定的顺序依次选房，房源选完即止。认购申请家庭选房时，只能在其认购意向项目中选择一套房源。
五、配售程序
（一）网上申请认购
有意申购的认购申请家庭，应登录深圳市住房和建设局官方网站在线提交认购申请。具体路径为：登录深圳市住房和建设局官方网站->“政务服务”->“服务主题”->“住房保障服务”->“安居型商品房认购申请”（“住房保障个人服务窗口”上方）。
网上申请认购时间为：2026年9月30日9:00至2026年10月18日18:00。2026年10月18日18:00前未完成网上认购的，视为放弃认购。认购申请家庭需调整认购意向的，应当于2026年10月18日18:00前，登录深圳市住房和建设局官方网站自行变更，逾期不予调整。
认购申请家庭已签订其它保障性住房项目认购协议书且仍有效的，不接受此次认购申请。
（二）看房
看房安排以《关于安居型商品房配售有关事项的通知》（2026077-1）为准。
（三）认购资格审核结果公示
认购结束后，深圳市住房保障署将审核认购申请家庭的认购资格，审核结果将通过深圳市住房和建设局官方网站公示5个工作日。认购申请家庭如需放弃本次认购，应当在公示期内，通过电脑登录深圳市住房和建设局官方网站提交网上放弃认购申请，逾期不予受理。
认购申请家庭对资格审核结果有异议的，应当在公示期间持相关证明材料向深圳市住房保障署提出异议申请。公示期满后，不再受理认购申请家庭异议申请。
深圳市住房保障署对认购申请家庭异议申请进行复核。异议成立的，更正认购申请家庭审核结果，并在深圳市住房和建设局官方网站发布终审合格认购申请家庭名单。
（四）公证摇号
终审合格认购申请家庭名单发布后，深圳市住房保障署将发布本批次住房配售摇号公告。由公证处对终审合格的第二、三队列认购申请家庭，通过摇号方式分别确定本批次住房两房户型和三房户型的选房顺序号，摇号结果在深圳市住房和建设局官方网站发布。
（五）发布选房通告
根据本通告第四条选房方式确定的选房顺序，分别确定本批次住房终审合格认购申请家庭的选房顺序及选房名单，并在深圳市住房和建设局官方网站发布本批次住房的选房通告及选房名单、选房顺序。
（六）选房及签约
选房通告及选房名单、选房排位发布后，认购申请家庭即可登录深圳市住房和建设局官方网站，在线打印《选房通知书》。
认购申请家庭须按《选房通知书》规定的时间到指定地点选房，并按照选房排位顺序依次选择其所在选房队列及其认购意向项目中的一套住房，房源选完即止。
认购申请家庭选定房号后，应当签订认购协议书。
认购申请家庭应按照认购协议书的规定时间缴纳购房款并签订安居型商品房买卖合同。未在规定时间内缴纳购房款、签订买卖合同的，视为放弃本次认购。
六、其他提示
（一）认购申请家庭认购资格的审核时点为认购截止日。认购申请家庭如住房、人口、人才认定、户籍、婚姻、抚恤定补优抚和残疾等信息发生变化，须在认购截止日前，登录深圳市住房和建设局官方网站“住房保障服务”页面在线提交信息变更申请，或持相关证明材料到深圳市政务服务中心西厅（地址：福田区福中三路市民中心B区一层南部深圳市政务服务中心西厅，咨询电话：0755-88631666）现场（节假日除外）提交信息变更申请。
（二）认购申请家庭在认购截止日后至签订安居型商品房买卖合同前，住房、婚姻、人口、户籍等情况发生变化的，应当如实申报。因信息发生变化导致不再符合认购资格或住房面积标准或轮候条件的，将取消认购申请家庭的认购资格或轮候资格，且不予签订安居型商品房买卖合同。上述信息发生变化后未及时变更，且不再符合认购资格或住房面积标准或轮候条件的，将依照《深圳市保障性住房条例》及相关法律、法规、规章予以处理。
其中，属于离婚情形的，申请人及原配偶须共同前往深圳市住房保障署办理信息变更，由符合条件的一方继续认购住房；双方都符合条件的，可协商确定其中一方继续认购住房。
（三）生成的认购编号仅对本批次住房配售有效。
（四）本批次住房选房结束后如有剩余房源，将结合项目配售情况开展后续工作，具体方式及程序将另行通告。
（五）业务咨询地址及电话
深圳市住房保障署联系地址：福田区红荔西路莲花大厦东面一楼（深圳市住房保障署联系服务群众工作室），业务咨询电话：0755-88631666。接听时间：工作日9:00-12:00，14:00-18:00。
（六）市民如发现违法违规线索，可通过来电、来信、来访等方式向深圳市住房保障主管部门投诉、举报，电话：0755-23913749。接听时间：工作日9:00-12:00，14:00-18:00。
附件：认购操作指引
深圳市住房保障署
2026年9月29日',NULL,'2026-11-07 03:25:44');
INSERT INTO "notices" VALUES(4,'深圳','市住建局',NULL,'住保售〔2026〕073号批次','综合公告','关于面向人才配售住房有关事项的通知（2026073-1）','2026-09-28','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_13000618.html','','',NULL,'2026-11-07 03:25:44');
INSERT INTO "notices" VALUES(5,'深圳','市住建局',228,'住保售〔2026〕073号批次','认购通告','深圳市住房保障署面向人才配售住房通告（住保售〔2026〕073号）','2026-09-28','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_13000614.html','根据工作安排，现就安居华越龙苑项目住房（以下简称“本批次住房”）面向高层次人才等群体配售的申请条件、房源安排、选房规则、配售流程等有关事项通告如下： 一、申请条件 按照本批次住房户型面积标准，认购申请家庭的资格条件分为六个队列，具体如下： ','根据工作安排，现就安居华越龙苑项目住房（以下简称“本批次住房”）面向高层次人才等群体配售的申请条件、房源安排、选房规则、配售流程等有关事项通告如下：
一、申请条件
按照本批次住房户型面积标准，认购申请家庭的资格条件分为六个队列，具体如下：
（一）第一队列。申请人属于经深圳市人力资源和社会保障局认定的国家级领军人才、海外A类高层次人才、“鹏城优才卡”尊鹏卡持卡人、钻石卡持卡人，或者具有正高级职称的专业技术人才。申请人在本市全职工作，不受户籍、缴纳社会保险（养老保险或者医疗保险，不含少儿医疗保险，下同）条件限制。不受家庭人口数限制。申请人为单身的，应当年满30周岁。
（二）第二队列。申请人属于经深圳市人力资源和社会保障局认定的地方级领军人才、海外B类高层次人才、“鹏城优才卡”白金卡持卡人。申请人具有本市户籍，在本市正常缴纳社会保险。不受家庭人口数限制。申请人为单身的，应当年满30周岁。
（三）第三队列。申请人属于经深圳市人力资源和社会保障局认定的后备级人才、海外C类高层次人才、“鹏城优才卡”金卡、银卡持卡人，或者深圳市人才主管部门备案的高精尖缺人才（2021年以来成功申报国家重大人才工程的人才）。申请人具有本市户籍，在本市正常缴纳社会保险。不受家庭人口数限制。申请人为单身的，应当年满30周岁。
（四）第四队列。申请人属于经区人力资源和社会保障局认定的高层次人才，或者区人才主管部门备案的高精尖缺人才，或者博士研究生，或者具有副高级职称的专业技术人才。申请人具有本市户籍，在本市正常缴纳社会保险，且参加本市社会保险累计缴纳2年以上。家庭人口数为3人及以上。申请人为单身的，应当年满30周岁。
（五）第五队列。申请人具有全日制本科及以上学历（含教育部认可的境外高等院校毕业的归国留学人员），或者属于符合深圳市产业发展需要的技师（国家职业资格二级及以上）。申请人具有本市户籍，在本市正常缴纳社会保险，且参加本市社会保险累计缴纳3年以上。家庭有3个以上未满18周岁的子女或者家庭人口数为5人以上且有2个未满18周岁的子女。
（六）第六队列。申请人具有全日制本科及以上学历（含教育部认可的境外高等院校毕业的归国留学人员），或者属于符合深圳市产业发展需要的技师（国家职业资格二级及以上）。申请人具有本市户籍，在本市正常缴纳社会保险，且参加本市社会保险累计缴纳3年以上。家庭人口数为4人且有2个未满18周岁的子女。
申请人配偶、未成年子女不受本市户籍限制，未具有本市户籍的申请人配偶在本市正常缴纳社会保险，但在本市退休的除外。
申请家庭的证书、“鹏城优才卡”、学历、职业技术资格、户籍、社保、年龄、家庭人口数等以认购截止日的情况确定。
申请家庭在认购截止日前，还应符合下列条件：
1.申请人、共同申请人在本市未购买过准成本房、全成本房、社会微利房、全成本微利房、经济适用住房、限价商品房、安居型商品房等政策性住房，未享受过我市高层次人才购房补贴或者奖励补贴政策。
2.申请人、共同申请人在本市未拥有任何形式自有住房（含住房建设用地，下同）且在认购截止日前5年内未在本市转让过或者因离婚分割过自有住房。
申请人应当以家庭为单位提出本批次住房申请，申请人的配偶、未满18周岁(判定时点为本通告发布之日)的子女应当列为共同申请人，申请人年满18周岁的子女不能列为共同申请人。未满18周岁的子女列为共同申请人的，不影响其成年后单独组成家庭或者达到规定年龄后以单身居民身份申请深圳市住房保障。申请人父母、申请人配偶父母具有本市户籍的，可以作为共同申请人。
投靠子女取得深圳市户籍的居民，只能作为共同申请人。
家庭人口数按照符合条件的申请人、共同申请人的总人数予以确定。
二、申请材料
申请认购家庭应当通过线上提交以下材料：
（一）住房认购申请表；
（二）申请人的身份证、户口簿，共同申请人的身份证、户口簿（或出生证、收养证明、公证书等关系证明材料）及其他户籍证明；
（三）申请人配偶属现役军人的，提供军官证、士兵证；
（四）申请人或申请人配偶属港澳台居民的，提供香港永久性居民身份证、澳门永久性居民身份证、台湾居民来往大陆通行证等证明材料；
（五）申请人及共同申请人的婚姻状况证明（初婚的提供结婚证；离异的提供离婚证和离婚协议、生效的法院判决书或调解书等离婚证明材料；再婚的提供结婚证及前段婚姻离婚证明材料；丧偶的提供丧偶证明材料；未婚的无须提供婚姻状况证明）；
（六）申请人属于第一队列且非深圳户籍，需提供申请人在本市全职工作的证明，包括申请人与用人单位签订的劳动合同、纳税清单；
（七）以下人才证明材料之一：
1.深圳市人力资源和社会保障局出具的高层次人才证书或者发放的“鹏城优才卡”；
2.区人力资源和社会保障局出具的高层次人才证书或者发放的“鹏城优才卡”；
3.博士研究生学历证书；
4.正高级职称证书或者副高级职称证书，且具有用人单位评聘证明或者评聘证书，或者具有劳动合同证明和纳税清单证明；
5.本科或硕士研究生学历（学位）证书；
6.国家职业资格二级技师证书或国家职业资格一级高级技师证书；
（八）申请人或共同申请人属于残疾人的，提供在认购截止日前由残疾人联合会或退役军人管理部门颁发的有效残疾证。
三、房源安排
本批次配售房源共433套，其中，建筑面积约146-150平方米四房常规户型（以下简称“A类户型”）135套（含26套无障碍户型）、建筑面积约113-120平方米四房常规户型（以下简称“B类户型”）298套。
（一）第一队列可认购A类户型、B类户型。
（二）第二至第六队列可认购B类户型。
本通告发布前已购买本项目三房户型的家庭，符合本通告规定申请条件的，可以申请认购本批次住房，并根据申请条件纳入相应队列选房。选定四房户型住房后，再向开发建设单位退回原购买的住房。
四、配售方式
本批次住房实行集中认购、分队列摇号排序选房。
（一）认购申请方式
认购申请家庭应线上分别提交A类户型、B类户型的认购申请。其中，第一队列认购申请家庭可以同时提交A类户型、B类户型中的两个或一个户型的认购申请。
（二）选房方式
本批次住房按队列分别组织选房。
选房顺序依次为第一队列、第二队列、第三队列、第四队列、第五队列、第六队列。同一选房队列认购申请家庭按公证摇号确定的顺序依次选房。认购申请家庭仅能选择已提交认购申请户型的房源。
房源选完即止，认购申请家庭选房时，只能在其认购意向项目中选择一套房源。
五、配售程序
（一）线上申请认购
申请人进入深圳市住房和建设局官方网站—政务服务—服务主题—住房保障服务—面向人才配售住房申请（“住房保障个人服务窗口”上方）填报申请信息，线上提交申请材料，同时签署诚信申报声明，对申请材料和申报信息的真实性、准确性、合法性负责。认购申请家庭可在规定时间内登录信息平台提交人才住房认购申请并取得申请受理回执号。
线上申请认购时间为：2026年9月28日18:00至2026年10月18日18:00。认购截止日前未线上提交认购申请的，视为放弃认购，认购截止日后不再受理认购申请。认购申请家庭需调整认购意向的，应当于认购截止日前登录深圳市住房和建设局官方网站进行变更，逾期不予变更。
认购申请家庭已签订其它保障性住房项目认购协议书且仍有效的，不接受此次认购申请。
（二）看房
看房安排以《关于面向人才配售住房有关事项的通知（2026073-1）》为准。
（三）认购资格审核结果公示
深圳市住房保障署会同相关部门对全部认购申请家庭进行资格审核。审核结果将在政府网站公示5个工作日。认购申请家庭如需放弃本次认购申请，应当在公示期内登录深圳市住房和建设局官方网站提交放弃认购申请。
认购申请家庭对资格审核结果有异议的，应当在公示期间持相关证明材料向深圳市住房保障署提出异议申请。公示期满后，不再受理认购申请家庭异议申请。
深圳市住房保障署对认购申请家庭异议申请进行复核。异议成立的，更正认购申请家庭审核结果，并在深圳市住房和建设局官方网站发布终审合格认购申请家庭名单。
（四）公证摇号
终审合格认购申请家庭名单发布后，深圳市住房保障署将发布本批次住房配售摇号公告。由公证处对终审合格的认购申请家庭，通过摇号方式分别确定本批次住房各队列认购申请家庭的选房顺序号，摇号结果在深圳市住房和建设局官方网站发布。
（五）发布选房通告
深圳市住房保障署根据公证摇号确定的选房顺序号，分别确定本批次住房终审合格认购申请家庭的选房顺序及选房名单，并在深圳市住房和建设局官方网站发布本批次住房的选房通告及选房名单、选房顺序。
（六）选房及签约
选房通告及选房顺序、选房名单发布后，认购申请家庭即可登录深圳市住房和建设局官方网站，在线打印《选房通知书》。
认购申请家庭须按《选房通知书》规定时间到指定地点选房，并按照选房顺序依次选房，房源选完即止。
认购申请家庭选定房号后，应当签订认购协议书。
认购申请家庭应按照认购协议书的规定时间缴纳购房款并签订住房买卖合同。未在规定时间内缴纳购房款、签订买卖合同的，视为主动放弃本次认购。
六、其他提示
（一）符合本通告规定条件的安居型商品房在册轮候人可认购本批次住房，签订买卖合同后，自动退出安居型商品房轮候册。
（二）本批次住房的产权管理、使用和处分、监督管理和法律责任等内容按照《深圳市保障性住房条例》《深圳市安居型商品房建设和管理暂行办法》及相关规定执行。购房人的不动产权证书登记为安居型商品房。签订买卖合同满10年的，可按照届时安居型商品房取得完全产权的相关政策规定，申请取得住房完全产权。
（三）线上提交认购申请后至签订买卖合同前，申请人、共同申请人的住房、家庭人口、户籍、婚姻、学历学位、职业技术资格、深圳市高层次人才证书、“鹏城优才卡”等信息发生变化的，应及时登录深圳市住房和建设局官方网站—政务服务—服务主题—住房保障服务—面向人才配售住房申请（“住房保障个人服务窗口”上方）变更相关信息。信息变更后经审核不再符合申请条件或认购住房户型面积标准的，将取消认购申请家庭的认购资格。上述信息发生变化后未及时变更，且不再符合申请条件或认购住房户型面积标准的，将依照《深圳市保障性住房条例》及相关法律、法规、规章予以处理。
有关信息变化且属于离婚情形的，申请人及原配偶须共同前往深圳市住房保障署办理信息变更，由符合条件的一方继续认购住房；双方都符合条件的，可协商确定其中一方继续认购住房。
（四）生成的认购编号仅对本批次住房配售有效。
（五）根据《深圳经济特区房地产转让条例》有关规定，认购申请家庭签订买卖合同后，若买受人中包含境外（含港澳台）人士，应当履行合同公证手续。未提供合同公证文书的，合同将不予备案。
（六）本批次住房选房结束后如有剩余房源，将结合项目配售情况开展后续工作，具体方式及程序将另行通告。
（七）业务咨询地址及电话
安居华越龙苑项目咨询电话0755-86266999，接听时间：9:00-18:00。
深圳市住房保障署联系地址：福田区红荔西路莲花大厦东面一楼（深圳市住房保障署联系服务群众工作室），咨询电话：0755-88631666。接听时间：工作日9:00-12:00，14:00-18:00。
（八）市民如发现违法违规线索，可通过来电、来信、来访等方式向深圳市住房主管部门投诉、举报。深圳市住房和建设局投诉举报电话：0755-23913749。
深圳市住房保障署
2026年9月28日',NULL,'2026-11-07 03:25:45');
INSERT INTO "notices" VALUES(6,'深圳','市住建局',233,'住保售〔2026〕072号批次','认购通告','深圳市住房保障署安居型商品房配售通告（住保售〔2026〕072号）','2026-09-22','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_12995217.html','《关于安居型商品房配售有关事项的通知》（2026072-1）已在深圳市住房和建设局官方网站发布。现就伟城贤德瑞府项目安居型商品房（以下简称本批次住房）的配售对象、房源安排、选房方式、配售程序等有关事项通告如下： 一、申请条件 （一）认购本批','《关于安居型商品房配售有关事项的通知》（2026072-1）已在深圳市住房和建设局官方网站发布。现就伟城贤德瑞府项目安居型商品房（以下简称本批次住房）的配售对象、房源安排、选房方式、配售程序等有关事项通告如下：
一、申请条件
（一）认购本批次住房，按照申请家庭资格条件分为三个队列，具体如下：
第一队列：属于深圳市安居型商品房在册轮候家庭且仍符合安居型商品房轮候申请条件，或在本通告认购截止前符合安居型商品房申请条件且经深圳市人力资源和社会保障局认定的领军人才（人才证书在有效期内或人才证书虽不在有效期内但期末评估合格）。
第二队列：申请人、共同申请人均具有本市户籍，申请人配偶属现役军人的，可以不受户籍限制，申请人的未成年子女因就学而将户籍迁出本市的，视为具有本市户籍；申请人参加本市社会保险累计缴费5年以上，申请人为本科及以上学历的，参加本市社会保险累计缴费3年以上；申请人为单身的，应当年满35周岁。
第三队列：申请人具有本市户籍；申请人参加本市社会保险累计缴费5年以上，申请人为本科及以上学历的，参加本市社会保险累计缴费3年以上；申请人配偶、未成年子女不受本市户籍限制，未具有本市户籍的申请人配偶在本市正常缴纳社会保险，但在本市退休的除外；申请人为单身的，应当年满30周岁。
属于以下特殊群体的，不受缴纳社会保险时间限制：1.申请人、共同申请人属于经民政部门或退役军人管理部门认定的抚恤定补优抚对象；2.申请人、共同申请人属于经残疾人联合会或退役军人管理部门认定的残疾人。
（二）申请家庭在认购截止日前，还应符合下列条件：
1.申请人、共同申请人均未在本市拥有任何形式自有住房，且在申请受理日之前5年内未在本市转让过或者因离婚分割过自有住房。
2.申请人、共同申请人在本市未购买过准成本房、全成本房、社会微利房、全成本微利房、单位集资建房、经济适用住房、安居型商品房（含面向人才配售）、共有产权住房等政策性住房，未享受过人才购房补贴、高层次人才奖励补贴等购房优惠政策。
（三）申请人应当以家庭为单位提出本批次住房申请，申请人的配偶、未满18周岁(判定时点为本通告发布之日)的子女应当列为共同申请人，申请人年满18周岁的子女不能列为共同申请人。未满18周岁的子女列为共同申请人的，不影响其成年后单独组成家庭或者达到规定年龄后以单身居民身份申请深圳市住房保障。申请人父母、申请人配偶父母具有本市户籍的，可以作为共同申请人。投靠子女取得深圳市户籍的居民，只能作为共同申请人。
二、申请材料
深圳市安居型商品房在册轮候家庭无需另行提交材料。其他申请认购家庭应当通过线上提交以下材料：
（一）住房认购申请表；
（二）申请人的身份证、户口簿，共同申请人的身份证、户口簿（或出生证、收养证明、公证书等关系证明材料）及其他户籍证明；
（三）申请人配偶属现役军人的，提供军官证、士兵证；
（四）申请人及共同申请人的婚姻状况证明（初婚的提供结婚证；离异的提供离婚证和离婚协议、生效的法院判决书或调解书等离婚证明材料;再婚的提供结婚证及前段婚姻离婚证明材料；丧偶的提供丧偶证明材料；未婚的无须提供婚姻状况证明）。
（五）以下人才证明材料之一：
1.学历（学位）证书；
2.由深圳市人力资源和社会保障局出具的高层次人才证书；
（六）申请人或共同申请人属于残疾人的，提供在认购截止日前由残疾人联合会或退役军人管理部门颁发的有效残疾人证。
三、房源安排
本批次配售住房共246套，其中：建筑面积约70平方米两房户型163套、建筑面积约90平方米三房户型83套（含三房无障碍住房13套）。
（一）单身居民及二至三人家庭可根据自身意愿认购本批次住房的两房户型。
（二）领军人才、四人及以上家庭可根据自身意愿认购本批次住房的两房户型或三房户型（含三房无障碍户型）。
四、配售方式
本批次住房实行集中认购、分队列摇号排序选房。
（一）认购申请方式
认购申请家庭可线上提交认购意向。
（二）选房方式
本批次住房按两房户型和三房户型分别组织选房。
第一队列第一序位为领军人才认购申请家庭，其选房排位排在本次认购的所有轮候家庭之前，领军人才之间的选房排位按照提交安居型商品房申请时间的先后顺序确定。第二序位为按深圳市安居型商品房轮候册排位确定的在册认购申请家庭，其中申请人或共同申请人如属民政部门或退役军人管理部门认定的抚恤定补优抚对象，或为拥有残疾人联合会或退役军人管理部门颁发的有效残疾人证的残疾人，有优先选房权利，选房排位依据深圳市安居型商品房轮候册的轮候排序确定。
第二、三队列选房顺序通过公证摇号确定。
选房顺序依次为第一队列、第二队列、第三队列，每个队列的认购申请家庭按确定的顺序依次选房，房源选完即止。认购申请家庭选房时，只能在其认购意向项目中选择一套房源。
五、配售程序
（一）网上申请认购
有意申购的认购申请家庭，应登录深圳市住房和建设局官方网站在线提交认购申请。具体路径为：登录深圳市住房和建设局官方网站->“政务服务”->“服务主题”->“住房保障服务”->“安居型商品房认购申请”（“住房保障个人服务窗口”上方）。
网上申请认购时间为：2026年9月23日9:00至2026年10月11日18:00。2026年10月11日18:00前未完成网上认购的，视为放弃认购。认购申请家庭需调整认购意向的，应当于2026年10月11日18:00前，登录深圳市住房和建设局官方网站自行变更，逾期不予调整。
认购申请家庭已签订其他保障性住房项目认购协议书且仍有效的，不接受此次认购申请。
（二）看房
看房安排以《关于安居型商品房配售有关事项的通知》（2026072-1）为准。
（三）认购资格审核结果公示
认购结束后，深圳市住房保障署将审核认购申请家庭的认购资格，审核结果将通过深圳市住房和建设局官方网站公示5个工作日。认购申请家庭如需放弃本次认购，应当在公示期内，通过电脑登录深圳市住房和建设局官方网站提交网上放弃认购申请，逾期不予受理。
认购申请家庭对资格审核结果有异议的，应当在公示期间持相关证明材料向深圳市住房保障署提出异议申请。公示期满后，不再受理认购申请家庭异议申请。
深圳市住房保障署对认购申请家庭异议申请进行复核。异议成立的，更正认购申请家庭审核结果，并在深圳市住房和建设局官方网站发布终审合格认购申请家庭名单。
（四）公证摇号
终审合格认购申请家庭名单发布后，深圳市住房保障署将发布本批次住房配售摇号公告。由公证处对终审合格的第二、三队列认购申请家庭，通过摇号方式分别确定本批次住房两房户型和三房户型的选房顺序号，摇号结果在深圳市住房和建设局官方网站发布。
（五）发布选房通告
根据本通告第四条选房方式确定的选房顺序，分别确定本批次住房终审合格认购申请家庭的选房顺序及选房名单，并在深圳市住房和建设局官方网站发布本批次住房的选房通告及选房名单、选房顺序。
（六）选房及签约
选房通告及选房名单、选房排位发布后，认购申请家庭即可登录深圳市住房和建设局官方网站，在线打印《选房通知书》。
认购申请家庭须按《选房通知书》规定的时间到指定地点选房，并按照选房排位顺序依次选择其所在选房队列及其认购意向项目中的一套住房，房源选完即止。
认购申请家庭选定房号后，应当签订认购协议书。
认购申请家庭应按照认购协议书的规定时间缴纳购房款并签订安居型商品房买卖合同。未在规定时间内缴纳购房款、签订买卖合同的，视为放弃本次认购。
六、其他提示
（一）认购申请家庭认购资格的审核时点为认购截止日。认购申请家庭如住房、人口、人才认定、户籍、婚姻、抚恤定补优抚和残疾等信息发生变化，须在认购截止日前，登录深圳市住房和建设局官方网站“住房保障服务”页面在线提交信息变更申请，或持相关证明材料到深圳市政务服务中心西厅（地址：福田区福中三路市民中心B区一层南部深圳市政务服务中心西厅，咨询电话：0755-88631666）现场（节假日除外）提交信息变更申请。
（二）认购申请家庭在认购截止日后至签订安居型商品房买卖合同前，住房、婚姻、人口、户籍等情况发生变化的，应当如实申报。因信息发生变化导致不再符合认购资格或住房面积标准或轮候条件的，将取消认购申请家庭的认购资格或轮候资格，且不予签订安居型商品房买卖合同。上述信息发生变化后未及时变更，且不再符合认购资格或住房面积标准或轮候条件的，将依照《深圳市保障性住房条例》及相关法律、法规、规章予以处理。
其中，属于离婚情形的，申请人及原配偶须共同前往深圳市住房保障署办理信息变更，由符合条件的一方继续认购住房；双方都符合条件的，可协商确定其中一方继续认购住房。
（三）生成的认购编号仅对本批次住房配售有效。
（四）本批次住房选房结束后如有剩余房源，将结合项目配售情况开展后续工作，具体方式及程序将另行通告。
（五）业务咨询地址及电话
深圳市住房保障署联系地址：福田区红荔西路莲花大厦东面一楼（深圳市住房保障署联系服务群众工作室），业务咨询电话：0755-88631666。接听时间：工作日9:00-12:00，14:00-18:00。
（六）市民如发现违法违规线索，可通过来电、来信、来访等方式向深圳市住房保障主管部门投诉、举报，电话：0755-23913749。接听时间：工作日9:00-12:00，14:00-18:00。
附件：认购操作指引
深圳市住房保障署
2026年9月22日',NULL,'2026-11-07 03:25:46');
INSERT INTO "notices" VALUES(7,'深圳','市住建局',NULL,'住保售〔2026〕072号批次','综合公告','关于安居型商品房配售有关事项的通知（2026072-1）','2026-09-22','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_12995212.html','','',NULL,'2026-11-07 03:25:46');
INSERT INTO "notices" VALUES(8,'深圳','市住建局',NULL,'住保售〔2026〕068号批次','综合公告','深圳市住房保障署关于安居型商品房选房的通告（住保售〔2026〕068号批次）','2026-09-22','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_12995184.html','','',NULL,'2026-11-07 03:25:46');
INSERT INTO "notices" VALUES(9,'深圳','市住建局',37,'2026068-1批次','选房通知','关于安居型商品房选房有关事项的通知（2026068-1批次）','2026-09-22','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_12995177.html','根据《深圳市住房保障署关于安居型商品房选房的通告》（住保售〔2026〕068号批次）以及《深圳市住房保障署关于安居型商品房认购资格终审结果的通告》（住保售〔2026〕068号批次）相关要求，现决定开展瑞璟公馆项目安居型商品房（住保售〔202','根据《深圳市住房保障署关于安居型商品房选房的通告》（住保售〔2026〕068号批次）以及《深圳市住房保障署关于安居型商品房认购资格终审结果的通告》（住保售〔2026〕068号批次）相关要求，现决定开展瑞璟公馆项目安居型商品房（住保售〔2026〕068号批次，以下简称“本批次住房”）的选房签约工作，有关事项通知如下：
一、选房有关事项
按照《深圳市住房保障署关于安居型商品房选房的通告》（住保售〔2026〕068号批次）确定的选房名单，选房时间、场次及地点等事项分别安排如下：
（一）选房时间
本批次住房两房户型队列、三房户型队列的选房时间为2026年9月27日下午，房源选完即止，具体选房场次及时间安排详见附件1。认购申请家庭应于2026年9月24日14:00起进入深圳市住房和建设局官方网站一>“政务服务”一>“服务主题”一>“住房保障服务”一>“安居型商品房认购申请”（“住房个人服务窗口”上方）一>登录系统后选择打印选房通知书。
（二）选房地点安排
选房地址：深圳市光明区马田街道科达一路与科达三路交汇处瑞璟公馆接待中心。
选房交通指引详见附件2。
二、选房规则
关于选房规则及有关提示请查阅《深圳市住房保障署关于安居型商品房选房的通告》（住保售〔2026〕068号批次）。
三、注意事项
（一）认购申请家庭应当按照选房通知书规定的时间，携带选房通知书、本人身份证原件以及申请人或共同申请人的储蓄卡（余额超过人民币2万元，用于缴纳2万元认购定金）到达指定地点参加选房。
（二）认购申请家庭选定房号后，应按规定当场缴纳认购定金人民币2万元，并签订认购协议书。
（三）选房工作结束后，于当日24:00前，认购申请家庭可登录深圳市住房和建设局网站→政务服务→服务主题→住房保障服务→住房保障服务主页→选房结果公示专栏查看选房结果。
（四）认购申请家庭委托其他人选房的，被委托人须提供经公证的选房委托书原件和被委托人身份证原件。
（五）已选房的认购申请家庭应按照认购协议书的约定按时缴纳购房款并签订买卖合同。未在规定时间内签订买卖合同的，视为放弃本次认购。
四、项目咨询电话
瑞璟公馆项目咨询电话：0755-26662667，接听时间：9:00-18:00。
附件：
1.瑞璟公馆项目认购申请家庭选房时间安排表
2.瑞璟公馆项目选房交通指引和注意事项
