INSERT INTO "notices" VALUES(102,'深圳','市住建局',NULL,'住保售〔2026〕049号批次','综合公告','深圳市住房保障署关于安居型商品房认购资格审核结果公示的通告（住保售〔2026〕049号批次）','2026-07-06','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_12880154.html','','',NULL,'2026-11-07 03:26:09');
