INSERT INTO "notices" VALUES(143,'深圳','市住建局',NULL,'住保售〔2026〕036号批次','综合公告','深圳市住房保障署关于安居型商品房选房的通告（住保售〔2026〕036号批次）','2026-06-04','https://zjj.sz.gov.cn/ztfw/zfbz/tzgg2017/content/post_12822713.html','','',NULL,'2026-11-07 03:26:16');
