INSERT INTO "notices" VALUES(192,'深圳','罗湖区',NULL,NULL,'轮候公示','罗湖区住房和建设局关于罗湖区户籍公共租赁住房轮候申请核查合格家庭信息公示的通告','2026-03-31','https://www.szlh.gov.cn/lhqzfhjsj/gkmlpt/content/12/12712/post_12712766.html','公示日期和方式：从2026年3月31日至2026年4月14日，通过罗湖区住房和建设局官方网站公示15天。','','[{"id": 1699421, "name": "罗湖区户籍公共租赁住房轮候申请核查合格家庭名单及相关信息表（受理时间：2025年12月1日至12月31日）.pdf", "type": "pdf", "mime": "application/pdf", "size": "277355", "url": "https://www.szlh.gov.cn/lhqzfhjsj/attachment/1/1699/1699421/12712766.pdf"}]','2026-11-07 03:26:40');
