INSERT INTO "notices" VALUES(234,'深圳','罗湖区',NULL,NULL,'轮候公示','罗湖区住房和建设局关于2025年第二批面向罗湖区户籍公共租赁住房在册轮候家庭配租住房的通告','2025-11-24','https://www.szlh.gov.cn/lhqzfhjsj/gkmlpt/content/12/12511/post_12511972.html','网上认租时间为2025年11月24日10:00至2025年12月3日18:00，共10天。咨询电话：0755-25620382、25650918；网上认租、资格核查、结果公示、选房签约咨询电话：0755-25650868、22185615。','','[{"id": 1652475, "name": "特殊家庭解释.docx", "type": "doc", "mime": "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "size": "16820", "url": "https://www.szlh.gov.cn/lhqzfhjsj/attachment/1/1652/1652475/12511972.docx"}]','2026-11-07 03:26:52');
