INSERT INTO "notices" VALUES(454,'深圳','宝安区',NULL,NULL,'综合公告','深圳市人才安居集团有限公司、深圳市宝安人才安居有限公司关于面向人才配售安居鸿栖台、安居福汇阁项目住房有关事项的通知','2023-09-09','https://www.baoan.gov.cn/gkmlpt/content/10/10826/post_10826925.html','经深圳市宝安区住房和建设局批准，安居鸿栖台、安居福汇阁项目本批次住房（以下简称本批次住房）将面向符合条件的人才配售。现将本批次住房基本情况、配售价格、看房安排等有关事项通知如下。','','[{"id": 1351217, "name": "1.安居鸿栖台全景看房二维码.doc", "type": "doc", "mime": "application/msword", "size": "12800", "url": "http://www.baoan.gov.cn/attachment/1/1351/1351217/10826925.doc"}, {"id": 1351218, "name": "2.安居鸿栖台售房说明书.pdf", "type": "pdf", "mime": "application/pdf", "size": "10953311", "url": "http://www.baoan.gov.cn/attachment/1/1351/1351218/10826925.pdf"}, {"id": 1351219, "name": "3.安居福汇阁全景看房二维码、预约现场看房二维码.doc", "type": "doc", "mime": "application/msword", "size": "228864", "url": "http://www.baoan.gov.cn/attachment/1/1351/1351219/10826925.doc"}, {"id": 1351220, "name": "4.安居福汇阁现场看房交通指引和注意事项.docx", "type": "doc", "mime": "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "size": "348968", "url": "http://www.baoan.gov.cn/attachment/1/1351/1351220/10826925.docx"}, {"id": 1351221, "name": "5.安居福汇阁售房说明书.pdf", "type": "pdf", "mime": "application/pdf", "size": "21203328", "url": "http://www.baoan.gov.cn/attachment/1/1351/1351221/10826925.pdf"}, {"id": 1351222, "name": "6.安居鸿栖台住房房源价格表（两房户型、三房户型）.xls", "type": "doc", "mime": "application/vnd.ms-excel", "size": "22016", "url": "http://www.baoan.gov.cn/attachment/1/1351/1351222/10826925.xls"}, {"id": 1351223, "name": "7.安居福汇阁住房房源价格表（两房户型、三房户型）.xls", "type": "doc", "mime": "application/vnd.ms-excel", "size": "53760", "url": "http://www.baoan.gov.cn/attachment/1/1351/1351223/10826925.xls"}]','2026-11-07 03:27:13');
INSERT INTO "notices" VALUES(455,'深圳','宝安区',NULL,NULL,'综合公告','深圳市宝安区住房和建设局关于安居鸿栖台、安居福汇阁项目住房面向人才配售的通告','2023-09-09','https://www.baoan.gov.cn/gkmlpt/content/10/10826/post_10826924.html','《深圳市人才安居集团有限公司、深圳市宝安人才安居有限公司关于面向人才配售安居鸿栖台、安居福汇阁项目住房有关事项的通知》已在深圳市宝安区政府在线网站发布。现就安居鸿栖台、安居福汇阁项目本批次住房（以下简称本批次住房）的申请条件、房源安排、选房规则、配售流程等有关事项通告如下。','',NULL,'2026-11-07 03:27:13');
