INSERT INTO "notices" VALUES(483,'深圳','宝安区',NULL,NULL,'综合公告','深圳市宝安区住房和建设局关于安居鸿栖台、安居福汇阁项目常态化配售住房（2023年5月批次）认购资格审核结果公示的通告','2023-06-02','https://www.baoan.gov.cn/gkmlpt/content/10/10627/post_10627572.html','安居鸿栖台、安居福汇阁项目常态化配售住房（2023年5月批次）（以下简称“本批次住房”）认购工作已于2023年5月31日18:00结束，共2661户家庭提交认购申请。深圳市宝安区住房和建设局会同相关部门进行了审核，现将审核结果公示通告如下。','','[{"id": 1302813, "name": "1.认购安居鸿栖台项目常态化配售住房（2023年5月批次）两房户型的第一队列审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "721894", "url": "http://www.baoan.gov.cn/attachment/1/1302/1302813/10627572.pdf"}, {"id": 1302814, "name": "2.认购安居鸿栖台项目常态化配售住房（2023年5月批次）两房户型的第二队列审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "759032", "url": "http://www.baoan.gov.cn/attachment/1/1302/1302814/10627572.pdf"}, {"id": 1302815, "name": "3.认购安居鸿栖台、安居福汇阁项目常态化配售住房（2023年5月批次）三房户型的第一队列审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "505416", "url": "http://www.baoan.gov.cn/attachment/1/1302/1302815/10627572.pdf"}, {"id": 1302816, "name": "4.认购安居鸿栖台、安居福汇阁项目常态化配售住房（2023年5月批次）三房户型的第二队列审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "230656", "url": "http://www.baoan.gov.cn/attachment/1/1302/1302816/10627572.pdf"}]','2026-11-07 03:27:22');
