INSERT INTO "notices" VALUES(495,'深圳','宝安区',NULL,NULL,'综合公告','深圳市宝安区住房和建设局关于安居鸿栖台、安居福汇阁项目住房认购资格审核结果公示的通告','2023-04-07','https://www.baoan.gov.cn/gkmlpt/content/10/10529/post_10529882.html','安居鸿栖台、安居福汇阁项目住房（以下简称“本批次住房”）认购工作已于2023年3月23日24:00结束，共9332户家庭提交认购申请。深圳市宝安区住房和建设局会同相关部门进行了审核，现将审核结果公示通告如下。','','[{"id": 1282975, "name": "1.认购安居福汇阁项目住房两房户型第一队列的审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "1364423", "url": "http://www.baoan.gov.cn/attachment/1/1282/1282975/10529882.pdf"}, {"id": 1282976, "name": "2.认购安居福汇阁项目住房两房户型第二队列的审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "1353433", "url": "http://www.baoan.gov.cn/attachment/1/1282/1282976/10529882.pdf"}, {"id": 1282977, "name": "3.认购安居鸿栖台、安居福汇阁项目住房三房户型第一队列的审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "1001255", "url": "http://www.baoan.gov.cn/attachment/1/1282/1282977/10529882.pdf"}, {"id": 1285091, "name": "4.认购安居鸿栖台、安居福汇阁项目住房三房户型第二队列的审核合格名单.pdf", "type": "pdf", "mime": "application/pdf", "size": "859129", "url": "http://www.baoan.gov.cn/attachment/1/1285/1285091/10529882.pdf"}]','2026-11-07 03:27:24');
