INSERT INTO "notices" VALUES(560,'深圳','龙岗区',NULL,NULL,'综合公告','龙岗区住房和建设局关于公园里花园三期、丹郡花园、信义荔山御园、中骏蓝湾翠岭花园、远洋新干线君域花园公租房承租家庭集中续约有关事项的通知','2021-09-10','https://www.lg.gov.cn/lgzjj/gkmlpt/content/9/9121/post_9121031.html','','','[{"id": 850340, "name": "附件1：2021年10月31日到期个人租户续约条件合格名单及签约排期表.xlsx", "type": "doc", "mime": "application/zip", "size": "36975", "url": "https://www.lg.gov.cn/lgzjj/attachment/0/850/850340/9121031.xlsx"}, {"id": 850341, "name": "附件2：授权委托书.doc", "type": "doc", "mime": "application/msword", "size": "16384", "url": "https://www.lg.gov.cn/lgzjj/attachment/0/850/850341/9121031.doc"}]','2026-11-07 03:27:31');
