INSERT INTO "notices" VALUES(907,'深圳','光明区',NULL,NULL,'轮候公示','光明区住房和建设局关于2025年度第一批面向符合收入财产限额标准的光明区户籍在册轮候人配租公共租赁住房认租资格核查结果的公示','2025-07-02','https://www.szgm.gov.cn/gmzfhjsjcsgx/gkmlpt/content/12/12259/post_12259624.html','','','[{"id": 1599718, "name": "附件1：2025年度第一批面向符合收入财产限额标准的光明区户籍在册轮候认租家庭资格核查合格名单.xlsx", "type": "doc", "mime": "application/vnd.ms-excel", "size": "194048", "url": "https://www.szgm.gov.cn/gmzfhjsjcsgx/attachment/1/1599/1599718/12259624.xlsx"}, {"id": 1599717, "name": "附件2：2025年度第一批面向符合收入财产限额标准的光明区户籍在册轮候认租家庭资格核查不合格名单.xlsx", "type": "doc", "mime": "application/vnd.ms-excel", "size": "292864", "url": "https://www.szgm.gov.cn/gmzfhjsjcsgx/attachment/1/1599/1599717/12259624.xlsx"}]','2026-11-07 03:28:15');
