INSERT INTO "notices" VALUES(1119,'深圳','盐田区',NULL,NULL,'综合公告','深圳市盐田区“海安居二期电梯更换工程——土建部分”施工项目采购中标公示','2022-09-06','https://www.yantian.gov.cn/ytjsj/gkmlpt/content/10/10086/post_10086804.html','对深圳市“海安居二期电梯更换工程——土建部分”施工项目采用综合评分法进行采购。','',NULL,'2026-11-07 03:28:50');
