    total_planned_units INTEGER,
    planned_area REAL,
    address TEXT,
    status TEXT,
    notices_json TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(city, project_name)
);
